class Solution {
public:
    int maxCompatibilitySum(vector<vector<int>>& students, vector<vector<int>>& mentors) {
        int m = students.size(), n = students[0].size();
        vector<vector<int>> scores(m, vector<int>(m, 0));
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) scores[i][j]++;
                }
            }
        }
        vector<int> dp(1 << m, 0);
        for (int mask = 0; mask < (1 << m); mask++) {
            int sIdx = __builtin_popcount(mask);
            if (sIdx >= m) continue;
            for (int j = 0; j < m; j++) {
                if (!(mask & (1 << j))) {
                    int nextMask = mask | (1 << j);
                    dp[nextMask] = max(dp[nextMask], dp[mask] + scores[sIdx][j]);
                }
            }
        }
        return dp[(1 << m) - 1];
    }
};

class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length, n = students[0].length;
        int[][] scores = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) scores[i][j]++;
                }
            }
        }
        int[] dp = new int[1 << m];
        for (int mask = 0; mask < (1 << m); mask++) {
            int sIdx = Integer.bitCount(mask);
            if (sIdx >= m) continue;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) == 0) {
                    int nextMask = mask | (1 << j);
                    dp[nextMask] = Math.max(dp[nextMask], dp[mask] + scores[sIdx][j]);
                }
            }
        }
        return dp[(1 << m) - 1];
    }
}

var maxCompatibilitySum = function(students, mentors) {
  const m = students.length, n = students[0].length;
  const scores = Array.from({ length: m }, () => new Array(m).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < m; j++) {
      for (let k = 0; k < n; k++) {
        if (students[i][k] === mentors[j][k]) scores[i][j]++;
      }
    }
  }
  const dp = new Array(1 << m).fill(0);
  const popcount = (x) => {
    let c = 0;
    while (x > 0) { c += (x & 1); x >>= 1; }
    return c;
  };

  for (let mask = 0; mask < (1 << m); mask++) {
    const sIdx = popcount(mask);
    if (sIdx >= m) continue;
    for (let j = 0; j < m; j++) {
      if (!(mask & (1 << j))) {
        const nextMask = mask | (1 << j);
        dp[nextMask] = Math.max(dp[nextMask], dp[mask] + scores[sIdx][j]);
      }
    }
  }
  return dp[(1 << m) - 1];
};
